//! Unicode normalization (UAX #15) over UTF-16, without allocation.
//!
//! The tree had no normalization at all: RtlNormalizeString and NormalizeString were stubs,
//! FoldString's MAP_COMPOSITE/MAP_FOLDCZONE read old Wine tables that cover only part of
//! the job, and kernel32's IDN code skipped NFKC entirely. This crate is the one
//! implementation those callers share. Its tables (`tables.rs`) are generated by
//! `tools/codegen unorm` from the UCD vendored under `vendor/unicode-ucd/`.
//!
//! The algorithm streams one segment at a time: a starter (combining class 0) and the
//! non-starters after it, fully decomposed. When the next starter arrives the segment's
//! marks are put in canonical order (a stable sort by combining class) and, for the
//! composed forms, composed into the starter unless blocked. A segment left as its bare
//! starter may then combine with the new starter (Hangul LV + T, and the few starter
//! pairs the UCD has), which is the only way two starters ever compose: any character
//! between them blocks it.
//!
//! A segment holds `SEGMENT` code points. UAX #15's stream-safe format bounds a real
//! segment at 31; past `SEGMENT` the segment is emitted as it stands and a new one begins,
//! which only matters for adversarial input.
#![no_std]

mod tables;
pub use tables::UCD_VERSION;
use tables::{CANON, CCC, COMPAT, COMPOSE, DECOMP_DATA};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Form {
    /// Canonical composition.
    C,
    /// Canonical decomposition.
    D,
    /// Compatibility decomposition, then canonical composition.
    KC,
    /// Compatibility decomposition.
    KD,
}

impl Form {
    fn compat(self) -> bool {
        matches!(self, Form::KC | Form::KD)
    }
    fn compose(self) -> bool {
        matches!(self, Form::C | Form::KC)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Error {
    /// `dst` is too small; the full result needs this many UTF-16 units.
    BufferTooSmall(usize),
    /// A lone surrogate at this index of the source.
    InvalidChar(usize),
}

pub fn ccc(c: u32) -> u8 {
    match CCC.binary_search_by_key(&c, |e| e.0) {
        Ok(i) => CCC[i].1,
        Err(_) => 0,
    }
}

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn lookup(list: &[(u32, u16, u8)], c: u32) -> Option<&'static [u32]> {
    let i = list.binary_search_by_key(&c, |e| e.0).ok()?;
    let (_, off, len) = list[i];
    Some(&DECOMP_DATA[off as usize..off as usize + len as usize])
}

/// Calls `f` with each code point of `c`'s full decomposition.
fn decompose(c: u32, compat: bool, f: &mut impl FnMut(u32)) {
    if (S_BASE..S_BASE + S_COUNT).contains(&c) {
        let s = c - S_BASE;
        f(L_BASE + s / N_COUNT);
        f(V_BASE + (s % N_COUNT) / T_COUNT);
        if s % T_COUNT != 0 {
            f(T_BASE + s % T_COUNT);
        }
        return;
    }
    let found = if compat { lookup(&COMPAT, c).or_else(|| lookup(&CANON, c)) } else { lookup(&CANON, c) };
    match found {
        Some(seq) => seq.iter().for_each(|&d| f(d)),
        None => f(c),
    }
}

/// The primary composite of `a` + `b`, if there is one.
pub fn compose_pair(a: u32, b: u32) -> Option<u32> {
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a) && (a - S_BASE) % T_COUNT == 0 && (T_BASE + 1..T_BASE + T_COUNT).contains(&b) {
        return Some(a + (b - T_BASE));
    }
    COMPOSE.binary_search_by(|e| (e.0, e.1).cmp(&(a, b))).ok().map(|i| COMPOSE[i].2)
}

const SEGMENT: usize = 64;

struct Out<'a> {
    dst: &'a mut [u16],
    n: usize,
}

impl Out<'_> {
    fn put(&mut self, c: u32) {
        if c >= 0x10000 {
            let v = c - 0x10000;
            self.unit(0xD800 | (v >> 10) as u16);
            self.unit(0xDC00 | (v & 0x3FF) as u16);
        } else {
            self.unit(c as u16);
        }
    }
    fn unit(&mut self, u: u16) {
        if self.n < self.dst.len() {
            self.dst[self.n] = u;
        }
        self.n += 1;
    }
}

struct Segment {
    buf: [u32; SEGMENT],
    len: usize,
}

impl Segment {
    /// Canonical order: a stable insertion sort of the non-starter run by class.
    fn reorder(&mut self) {
        for i in 1..self.len {
            let c = self.buf[i];
            let k = ccc(c);
            if k == 0 {
                continue;
            }
            let mut j = i;
            while j > 0 && ccc(self.buf[j - 1]) > k {
                self.buf[j] = self.buf[j - 1];
                j -= 1;
            }
            self.buf[j] = c;
        }
    }

    /// Compose the marks into the leading starter, keeping blocked ones in place.
    fn compose(&mut self) {
        if self.len == 0 || ccc(self.buf[0]) != 0 {
            return;
        }
        let mut starter = self.buf[0];
        let mut kept = 1;
        let mut last: Option<u8> = None;
        for i in 1..self.len {
            let c = self.buf[i];
            let k = ccc(c);
            let unblocked = match last {
                None => true,
                Some(l) => l < k,
            };
            if unblocked {
                if let Some(p) = compose_pair(starter, c) {
                    starter = p;
                    continue;
                }
            }
            last = Some(k);
            self.buf[kept] = c;
            kept += 1;
        }
        self.buf[0] = starter;
        self.len = kept;
    }

    fn flush(&mut self, out: &mut Out, compose: bool) {
        self.reorder();
        if compose {
            self.compose();
        }
        for &c in &self.buf[..self.len] {
            out.put(c);
        }
        self.len = 0;
    }
}

/// Normalize `src` into `dst`, returning the number of UTF-16 units written. With an
/// empty `dst` this is a size query: the result is the length the output needs, and no
/// error is raised. Too small a non-empty `dst` gets `Error::BufferTooSmall(needed)`.
pub fn normalize(form: Form, src: &[u16], dst: &mut [u16]) -> Result<usize, Error> {
    let size_query = dst.is_empty();
    let mut out = Out { dst, n: 0 };
    let mut seg = Segment { buf: [0; SEGMENT], len: 0 };
    let compose = form.compose();
    let mut i = 0;
    while i < src.len() {
        let u = src[i];
        let c = if (0xD800..0xDC00).contains(&u) {
            match src.get(i + 1) {
                Some(&lo) if (0xDC00..0xE000).contains(&lo) => {
                    i += 1;
                    0x10000 + (((u as u32) - 0xD800) << 10) + ((lo as u32) - 0xDC00)
                }
                _ => return Err(Error::InvalidChar(i)),
            }
        } else if (0xDC00..0xE000).contains(&u) {
            return Err(Error::InvalidChar(i));
        } else {
            u as u32
        };
        i += 1;
        decompose(c, form.compat(), &mut |d| {
            if ccc(d) == 0 && seg.len > 0 {
                if compose {
                    seg.reorder();
                    seg.compose();
                    if seg.len == 1 && ccc(seg.buf[0]) == 0 {
                        if let Some(p) = compose_pair(seg.buf[0], d) {
                            seg.buf[0] = p;
                            return;
                        }
                    }
                }
                seg.flush(&mut out, compose);
            } else if seg.len == SEGMENT {
                seg.flush(&mut out, compose);
            }
            seg.buf[seg.len] = d;
            seg.len += 1;
        });
    }
    seg.flush(&mut out, compose);
    if !size_query && out.n > out.dst.len() {
        return Err(Error::BufferTooSmall(out.n));
    }
    Ok(out.n)
}

/// Whether `src` is already in `form` (by normalizing and comparing: there is no quick
/// check table).
pub fn is_normalized(form: Form, src: &[u16]) -> Result<bool, Error> {
    let mut buf = [0u16; 512];
    let mut done = 0;
    // Normalization never crosses a starter boundary, so compare window by window, each
    // ending just before a starter (never inside a surrogate pair). A normalized window
    // longer than `buf` is longer than the window itself, so it cannot be equal to it.
    while done < src.len() {
        let mut end = (done + 64).min(src.len());
        while end < src.len() && ((0xDC00..0xE000).contains(&src[end]) || ccc(src[end] as u32) != 0) {
            end += 1;
        }
        let window = &src[done..end];
        let n = match normalize(form, window, &mut buf) {
            Ok(n) => n,
            Err(Error::BufferTooSmall(_)) => return Ok(false),
            Err(e) => return Err(e),
        };
        if buf[..n] != *window {
            return Ok(false);
        }
        done = end;
    }
    Ok(true)
}

#[cfg(test)]
mod tests {
    extern crate std;
    use super::*;
    use std::vec::Vec;

    fn w(s: &str) -> Vec<u16> {
        s.encode_utf16().collect()
    }
    fn n(form: Form, s: &str) -> Vec<u16> {
        let src = w(s);
        let len = normalize(form, &src, &mut []).unwrap();
        let mut dst = std::vec![0u16; len];
        assert_eq!(normalize(form, &src, &mut dst), Ok(len));
        dst
    }

    #[test]
    fn known_answers() {
        // UAX #15 examples.
        assert_eq!(n(Form::D, "\u{1E0A}\u{0323}"), w("D\u{0323}\u{0307}"));
        assert_eq!(n(Form::C, "\u{1E0A}\u{0323}"), w("\u{1E0C}\u{0307}"));
        assert_eq!(n(Form::C, "A\u{030A}"), w("\u{00C5}"));
        assert_eq!(n(Form::C, "\u{212B}"), w("\u{00C5}")); // singleton: Angstrom sign
        assert_eq!(n(Form::KC, "\u{FB01}"), w("fi"));
        assert_eq!(n(Form::C, "\u{FB01}"), w("\u{FB01}"));
        assert_eq!(n(Form::KD, "\u{1E9B}\u{0323}"), w("s\u{0323}\u{0307}"));
        // Hangul both ways.
        assert_eq!(n(Form::D, "\u{AC01}"), w("\u{1100}\u{1161}\u{11A8}"));
        assert_eq!(n(Form::C, "\u{1100}\u{1161}\u{11A8}"), w("\u{AC01}"));
        // Composition exclusion: U+0958 stays decomposed under NFC.
        assert_eq!(n(Form::C, "\u{0958}"), w("\u{0915}\u{093C}"));
        // Supplementary plane, through surrogate pairs.
        assert_eq!(n(Form::KC, "\u{1D400}"), w("A"));
        // Blocked: the second acute cannot reach the starter past the first.
        assert_eq!(n(Form::C, "a\u{0301}\u{0301}"), w("\u{00E1}\u{0301}"));
    }

    #[test]
    fn size_query_short_buffer_and_lone_surrogates() {
        let src = w("\u{FB01}");
        assert_eq!(normalize(Form::KC, &src, &mut []), Ok(2));
        assert_eq!(normalize(Form::KC, &src, &mut [0u16; 1]), Err(Error::BufferTooSmall(2)));
        assert_eq!(normalize(Form::C, &[0x61, 0xD800], &mut [0u16; 4]), Err(Error::InvalidChar(1)));
        assert_eq!(normalize(Form::C, &[0xDC00], &mut [0u16; 4]), Err(Error::InvalidChar(0)));
    }

    #[test]
    fn is_normalized_matches_normalize() {
        assert_eq!(is_normalized(Form::C, &w("\u{00C5}")), Ok(true));
        assert_eq!(is_normalized(Form::C, &w("A\u{030A}")), Ok(false));
        assert_eq!(is_normalized(Form::D, &w("A\u{030A}")), Ok(true));
    }

    /// Exhaustive cross-check against an independent implementation: set
    /// UNORM_REFERENCE to a file of lines `CP NFC NFD NFKC NFKD` (hex code point
    /// sequences, space-joined within a field, fields separated by ';'), e.g. produced by
    /// Python's unicodedata at the same UCD version. Skipped when unset.
    #[test]
    fn reference_cross_check() {
        let Ok(path) = std::env::var("UNORM_REFERENCE") else { return };
        let text = std::fs::read_to_string(&path).unwrap();
        let hexs = |f: &str| -> Vec<u32> { f.split_whitespace().map(|h| u32::from_str_radix(h, 16).unwrap()).collect() };
        let utf16 = |cps: &[u32]| -> Vec<u16> {
            let mut v = Vec::new();
            for &c in cps {
                let mut b = [0u16; 2];
                v.extend_from_slice(char::from_u32(c).unwrap().encode_utf16(&mut b));
            }
            v
        };
        let mut bad = 0;
        let mut lines = 0;
        for line in text.lines() {
            let f: Vec<&str> = line.split(';').collect();
            let src = utf16(&hexs(f[0]));
            for (k, form) in [Form::C, Form::D, Form::KC, Form::KD].into_iter().enumerate() {
                let want = utf16(&hexs(f[k + 1]));
                let mut got = std::vec![0u16; 64];
                let n = normalize(form, &src, &mut got).unwrap();
                if got[..n] != want[..] {
                    bad += 1;
                    if bad <= 10 {
                        std::eprintln!("{form:?} {}: got {:04X?} want {:04X?}", f[0], &got[..n], want);
                    }
                }
            }
            lines += 1;
        }
        assert!(lines > 1000, "reference file has only {lines} lines");
        assert_eq!(bad, 0, "{bad} mismatches against {path}");
    }
}
